<template><section class="bio-nexus-page laboratory-page"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error" role="alert"><strong>No fue posible cargar Laboratorio.</strong><span>{{ loadError }}</span></div><header class="bio-nexus-page-header"><div><p class="bio-nexus-page-eyebrow">ConfiguraciÃ³n</p><h2>Laboratorio</h2><p class="bio-nexus-page-description">Administra la identidad, los datos institucionales, la impresiÃ³n y el correo del laboratorio.</p></div><BioNexusActionButton v-if="canUpdate" variant="primary" :loading="saving" :disabled="loading" @click="save">Guardar cambios</BioNexusActionButton></header><nav class="tabs" aria-label="Secciones de Laboratorio"><button v-for="tab in tabs" :key="tab.key" type="button" :class="{active:activeTab===tab.key}" @click="activeTab=tab.key">{{ tab.label }}</button></nav><div v-if="loading" class="bio-nexus-empty-state">Cargando configuraciÃ³n...</div><template v-else-if="laboratory"><LaboratoryLogoPanel v-show="activeTab==='logo'" :model="laboratory" :disabled="!canUpdate||saving" @upload="uploadLogo"/><LaboratoryGeneralPanel v-show="activeTab==='general'" :model="laboratory" :disabled="!canUpdate||saving"/><LaboratoryBillingPanel v-show="activeTab==='billing'" :model="laboratory" :taxes="taxes" :disabled="!canUpdate||saving" @add-tax="addTax" @delete-tax="removeTax"/><LaboratoryEmailPanel v-show="activeTab==='email'" :model="laboratory" :disabled="!canUpdate||saving"/></template></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import LaboratoryGeneralPanel from"@/components/laboratory/LaboratoryGeneralPanel.vue";import LaboratoryLogoPanel from"@/components/laboratory/LaboratoryLogoPanel.vue";import LaboratoryBillingPanel from"@/components/laboratory/LaboratoryBillingPanel.vue";import LaboratoryEmailPanel from"@/components/laboratory/LaboratoryEmailPanel.vue";import{useBioNexusToast}from"@/composables/useBioNexusToast";import{createLaboratoryTax,deleteLaboratoryTax,getLaboratory,getLaboratoryErrorMessage,getLaboratoryTaxes,updateLaboratory,updateLaboratoryTax,uploadLaboratoryLogo}from"@/services/laboratoryService";import{validateLaboratoryRequired}from"@/models/laboratory";import{useAuthorizationStore}from"@/stores/authorization";const authorization=useAuthorizationStore(),toast=useBioNexusToast(),laboratory=ref(null),loading=ref(false),saving=ref(false),loadError=ref(""),activeTab=ref("general"),taxes=ref([]);const tabs=Object.freeze([{key:"logo",label:"Logo"},{key:"general",label:"General"},{key:"billing",label:"Factura / Toma de muestra"},{key:"email",label:"EnvÃ­o por correo"}]);const canUpdate=computed(()=>authorization.hasPermission("laboratory.update"));async function load(){loading.value=true;try{[laboratory.value,taxes.value]=await Promise.all([getLaboratory(),getLaboratoryTaxes()])}catch(error){loadError.value=getLaboratoryErrorMessage(error,"No fue posible cargar la configuraciÃ³n.");toast.error(loadError.value)}finally{loading.value=false}}async function save(){const errors=validateLaboratoryRequired(laboratory.value);if(errors.length){toast.error(errors.join(" "));return}saving.value=true;try{laboratory.value=await updateLaboratory(laboratory.value.id,laboratory.value);await persistTaxes();toast.success("La configuraciÃ³n fue actualizada.")}catch(error){toast.error(getLaboratoryErrorMessage(error,"No fue posible guardar."))}finally{saving.value=false}}async function persistTaxes(){for(const tax of taxes.value){if(tax.id===-1)Object.assign(tax,await createLaboratoryTax(tax));else await updateLaboratoryTax(tax.id,tax)}}function addTax(){taxes.value.push({id:-1,localKey:"new-"+Date.now(),description:"",value:0,only_dollars:false,always_subtotal:false,hide:false})}async function removeTax(tax,index){try{if(tax.id!==-1)await deleteLaboratoryTax(tax.id);taxes.value.splice(index,1);toast.success("El impuesto fue eliminado.")}catch(error){toast.error(error?.message||"No fue posible eliminar el impuesto.")}}async function uploadLogo(file){if(!authorization.hasPermission("laboratory.upload-logo")){toast.error("La cuenta no tiene permiso para actualizar el logo.");return}saving.value=true;try{laboratory.value=await uploadLaboratoryLogo(file);toast.success("El logo fue actualizado.")}catch(error){toast.error(getLaboratoryErrorMessage(error,"No fue posible actualizar el logo."))}finally{saving.value=false}}onMounted(load);</script>
<style scoped>.laboratory-page{min-width:0}.tabs{display:flex;gap:var(--bio-nexus-space-1);overflow-x:auto;padding:var(--bio-nexus-space-1);border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface)}.tabs button{min-height:var(--bio-nexus-control-height);padding:0 var(--bio-nexus-space-4);border:0;border-radius:var(--bio-nexus-radius-sm);background:transparent;color:var(--bio-nexus-color-text-secondary);font:inherit;font-weight:var(--bio-nexus-font-weight-bold);white-space:nowrap;cursor:pointer}.tabs button.active{background:var(--bio-nexus-color-selection-soft);color:var(--bio-nexus-color-primary-strong);box-shadow:inset 0 -3px 0 var(--bio-nexus-color-accent)}</style>